76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /**
82	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
83	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    private final ClinicService clinicService;
88	
89	    private final OwnerMapper ownerMapper;
90	
91	    private final PetMapper petMapper;
92	
93	    private final VisitMapper visitMapper;
94	
95	    private final HttpServletRequest request;
96	
97	    /**
98	     * The HTTP header carrying a client-supplied idempotency token for owner creation.
99	     */
100	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
101	
102	    /**
103	     * Remembers the owner originally created under each seen {@code Idempotency-Key}. A create that
104	     * repeats a key already present here is replayed - the stored owner is returned with 200 instead
105	     * of creating a duplicate.
106	     */
107	    private final Map<String, OwnerDto> idempotentCreates = new ConcurrentHashMap<>();
108	
109	    public OwnerRestControllerV1(ClinicService clinicService,
110	                                 OwnerMapper ownerMapper,
111	                                 PetMapper petMapper,
112	                                 VisitMapper visitMapper,
113	                                 HttpServletRequest request) {
114	        this.clinicService = clinicService;
115	        this.ownerMapper = ownerMapper;
116	        this.petMapper = petMapper;
117	        this.visitMapper = visitMapper;
118	        this.request = request;
119	    }
