136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    /**
147	     * Rejects an owner payload that is missing or blank in any of the required fields
148	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
149	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
150	     * value as present; this guard closes that gap so a blank in any required field is
151	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
152	     * the name of each offending field.
153	     */
154	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
155	        List<String> missing = new ArrayList<>();
156	        if (isBlank(ownerFieldsDto.getFirstName())) {
157	            missing.add("firstName");
158	        }
159	        if (isBlank(ownerFieldsDto.getLastName())) {
160	            missing.add("lastName");
161	        }
162	        if (isBlank(normalizedAddress)) {
163	            missing.add("address");
164	        }
165	        if (isBlank(ownerFieldsDto.getCity())) {
166	            missing.add("city");
167	        }
168	        if (isBlank(ownerFieldsDto.getTelephone())) {
169	            missing.add("telephone");
170	        }
171	        if (!missing.isEmpty()) {
172	            throw new MissingOwnerFieldsException(missing);
173	        }
174	    }
175	
176	    private static boolean isBlank(String value) {
177	        return value == null || value.isBlank();
178	    }
179	
180	    /**
181	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
182	     */
183	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
184	
185	    /**
186	     * Required national-number length per country calling code. When the normalized E.164 number
187	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
188	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
189	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
190	     */
191	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
192	        "+61", 9,
193	        "+1", 10);
194	
195	    /**
196	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
197	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
198	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
199	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
200	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
201	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
202	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
203	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
204	     * translates to a 400.
205	     */
206	    private static String normalizeTelephone(String telephone) {
207	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
208	        String e164;
209	        if (cleaned.startsWith("+")) {
210	            e164 = cleaned;
211	        } else {
212	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
213	            e164 = "+61" + national;
214	        }
215	        if (!E164_PATTERN.matcher(e164).matches()) {
216	            throw new InvalidTelephoneException(telephone);
217	        }
218	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
219	            String code = rule.getKey();
220	            if (e164.startsWith(code)) {
221	                int nationalLength = e164.length() - code.length();
222	                if (nationalLength != rule.getValue()) {
223	                    throw new InvalidTelephoneException(telephone);
224	                }
225	                break;
226	            }
227	        }
228	        return e164;
229	    }
230	
231	    /**
232	     * Matches a well-formed postcode: exactly four digits.
233	     */
234	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
235	
236	    /**
237	     * The canonical region for each city that has one. A city absent from this table has no known
238	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
239	     * to derive an owner's locality.
240	     */
241	    private static final Map<String, String> CITY_REGION = Map.of(
242	        "Sydney", "NSW",
243	        "Melbourne", "VIC",
244	        "Brisbane", "QLD");
245	
246	    /**
247	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
248	     * VIC 3000-3099, QLD 4000-4099.
249	     */
250	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
251	        "NSW", new int[] {2000, 2099},
252	        "VIC", new int[] {3000, 3099},
253	        "QLD", new int[] {4000, 4099});
254	
255	    /**
256	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
257	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
258	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
259	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
260	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
261	     * exception handler translates to a 400.
262	     */
263	    private static void validatePostcode(String city, String postcode) {
264	        if (postcode == null) {
265	            return;
266	        }
267	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
268	            throw new InvalidPostcodeException(postcode);
269	        }
270	        String region = CITY_REGION.get(city);
271	        if (region == null) {
272	            return;
273	        }
274	        int[] range = REGION_POSTCODES.get(region);
275	        int value = Integer.parseInt(postcode);
276	        if (value < range[0] || value > range[1]) {
277	            throw new InvalidPostcodeException(postcode);
278	        }
279	    }
280	
281	    /**
282	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
283	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
284	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
285	     */
286	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
287	
288	    /**
289	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
290	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
291	     * fixed set so the block list is explicit and easy to extend.
292	     */
293	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
294	        "mailinator.com",
295	        "tempmail.com",
296	        "guerrillamail.com");
297	
298	    /**
299	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
300	     * optional). When present it must be a syntactically valid address whose domain is not on the
301	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
302	     * canonical form. An invalid or disposable-domain value is rejected via
303	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
304	     */
305	    private static String normalizeEmail(String email) {
306	        if (email == null) {
307	            return null;
308	        }
309	        if (!EMAIL_PATTERN.matcher(email).matches()) {
310	            throw new InvalidEmailException(email);
311	        }
312	        String normalized = email.toLowerCase(Locale.ROOT);
313	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
314	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
315	            throw new InvalidEmailException(email);
316	        }
317	        return normalized;
318	    }
319	
320	    /**
321	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
322	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
323	     * same identity only when this whole key matches: because the normalized telephone is part of
324	     * the key, two members of the same household (same {@code householdId}) with different
325	     * telephones have different identity keys. A {@code null} email contributes an empty middle
326	     * segment. This is the value returned to callers as {@code identityKey}.
327	     */
328	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
329	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
330	    }
331	
332	    /**
333	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
334	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
335	     * telephone, email and household checks are now expressed through the components of the single
336	     * identity key:
337	     * <ul>
338	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
339	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
340	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
341	     *       candidate email, being optional, is not compared, and existing owners without an email
342	     *       are skipped);</li>
343	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
344	     *       a household via {@code sharesHousehold}, in which case the household component is not
345	     *       compared.</li>
346	     * </ul>
347	     */
348	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
349	                                         String normalizedEmail, String householdId) {
350	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
351	        for (Owner existing : this.clinicService.findAllOwners()) {
352	            if (existing.isDeleted()) {
353	                continue;
354	            }
355	            String existingTelephone;
356	            try {
357	                existingTelephone = normalizeTelephone(existing.getTelephone());
358	            } catch (InvalidTelephoneException ex) {
359	                existingTelephone = null;
360	            }
361	            if (normalizedTelephone.equals(existingTelephone)) {
362	                throw new DuplicateTelephoneException(normalizedTelephone);
363	            }
364	            if (normalizedEmail != null) {
365	                String existingEmail = existing.getEmail();
366	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
367	                    throw new DuplicateEmailException(normalizedEmail);
368	                }
369	            }
370	            if (!sharesHousehold
371	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getPostcode()))) {
372	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
373	            }
374	        }
375	    }
376	
377	    /**
378	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
379	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
380	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
381	     * spacing do not defeat the duplicate-household check.
382	     */
383	    private static String collapse(String value) {
384	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
385	    }
386	
387	    /**
388	     * Normalizes an owner's address into a canonical form applied on every create: leading and
389	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
390	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
391	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
392	     * and returned, and is the form every address comparison (duplicate-household detection and the
393	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
394	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
395	     * so normalizing an already-normalized address is a no-op.
396	     */
397	    private static String normalizeAddress(String address) {
398	        if (address == null) {
399	            return "";
400	        }
401	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
402	        if (collapsed.isEmpty()) {
403	            return "";
404	        }
405	        String[] tokens = collapsed.split(" ");
406	        StringBuilder sb = new StringBuilder(collapsed.length());
407	        for (int i = 0; i < tokens.length; i++) {
408	            String token = tokens[i];
409	            switch (token) {
410	                case "ST" -> token = "STREET";
411	                case "RD" -> token = "ROAD";
412	                case "AVE" -> token = "AVENUE";
413	                default -> {
414	                }
415	            }
416	            if (i > 0) {
417	                sb.append(' ');
418	            }
419	            sb.append(token);
420	        }
421	        return sb.toString();
422	    }
423	
424	    /**
425	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
426	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
427	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
428	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
429	     * region derivation shared by the {@code customerCode} and the owner's locality.
430	     */
431	    private static String deriveRegion(String city, String postcode) {
432	        if (postcode != null) {
433	            try {
434	                int pc = Integer.parseInt(postcode.trim());
435	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
436	                    int[] bounds = range.getValue();
437	                    if (pc >= bounds[0] && pc <= bounds[1]) {
438	                        return range.getKey();
439	                    }
440	                }
441	            } catch (NumberFormatException ignored) {
442	                // not a numeric postcode; fall back to the city-to-region table
443	            }
444	        }
445	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
446	    }
447	
448	    /**
449	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
450	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
451	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
452	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
453	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
454	     */
455	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
456	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
457	    }
458	
459	    /**
460	     * De-duplicates a freshly computed {@code customerCode} against the codes already carried by
461	     * existing owners. When the base code is unused it is returned unchanged; otherwise
462	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
463	     * existing owner already holds. The count reflects the state prior to this create.
464	     */
465	    private String deduplicateCustomerCode(String baseCode) {
466	        Set<String> existingCodes = new HashSet<>();
467	        for (Owner existing : this.clinicService.findAllOwners()) {
468	            String code = existing.getCustomerCode();
469	            if (code != null) {
470	                existingCodes.add(code);
471	            }
472	        }
473	        if (!existingCodes.contains(baseCode)) {
474	            return baseCode;
475	        }
476	        int n = 2;
477	        while (existingCodes.contains(baseCode + "-" + n)) {
478	            n++;
479	        }
480	        return baseCode + "-" + n;
481	    }
482	
483	    /**
484	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
485	     * bytes of {@code value}.
486	     */
487	    private static String sha256HexPrefix(String value, int hexChars) {
488	        try {
489	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
490	            StringBuilder sb = new StringBuilder(hexChars);
491	            for (byte b : digest) {
492	                if (sb.length() >= hexChars) {
493	                    break;
494	                }
495	                sb.append(String.format("%02X", b));
496	            }
497	            return sb.substring(0, hexChars);
498	        } catch (NoSuchAlgorithmException ex) {
499	            throw new IllegalStateException("SHA-256 not available", ex);
500	        }
501	    }
502	
503	    /**
504	     * Builds the {@code membershipNumber} for a newly created owner, formatted
505	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
506	     * fiscal year of the {@code registrationDate} (e.g. {@code 'SMI-0007-M27'}). The year
507	     * segment therefore matches the owner's {@code fiscalYear}.
508	     */
509	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
510	        return String.format("%s-M%02d", customerCode, fiscalYearOf(registrationDate) % 100);
511	    }
512	
513	    /**
514	     * The fiscal year, as a four-digit year, of a business-day-adjusted date. The fiscal year
515	     * starts on 1 July and is labelled by the calendar year in which it ends: a date on or after
516	     * 1 July belongs to the fiscal year ending the following calendar year, while an earlier date
517	     * belongs to the fiscal year ending in its own year.
518	     */
519	    private static int fiscalYearOf(LocalDate date) {
520	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
521	    }
522	
523	    /**
524	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
525	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
526	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
527	     * it is a pure function of that pair, every owner in the same household - whether created first
528	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
529	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
530	     * segment.
531	     */
532	    private static String householdIdFor(String lastName, String postcode) {
533	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
534	        try {
535	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
536	            StringBuilder sb = new StringBuilder(12);
537	            for (byte b : digest) {
538	                if (sb.length() >= 12) {
539	                    break;
540	                }
541	                sb.append(String.format("%02x", b));
542	            }
543	            return sb.substring(0, 12);
544	        } catch (NoSuchAlgorithmException ex) {
545	            throw new IllegalStateException("SHA-256 not available", ex);
546	        }
547	    }
548	
549	    /**
550	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
551	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
552	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
553	     */
554	    private int countNamesakes(String firstName, String lastName) {
555	        int count = 0;
556	        for (Owner existing : this.clinicService.findAllOwners()) {
557	            if (firstName.equalsIgnoreCase(existing.getFirstName())
558	                && lastName.equalsIgnoreCase(existing.getLastName())) {
559	                count++;
560	            }
561	        }
562	        return count;
563	    }
564	
565	    /**
566	     * Counts the members of the household the new owner will belong to, as it stands after this
567	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
568	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
569	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
570	     * stored on the owner as its {@code householdMemberCount}.
571	     */
572	    private int countHouseholdMembers(String householdId) {
573	        int count = 1;
574	        for (Owner existing : this.clinicService.findAllOwners()) {
575	            if (householdId.equals(existing.getHouseholdId())) {
576	                count++;
577	            }
578	        }
579	        return count;
580	    }
581	
582	    /**
583	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
584	     * that is not a hard identity collision but shares the new owner's {@code lastName} (compared
585	     * case-insensitively) and {@code postcode} while carrying a different normalized telephone. The
586	     * new owner's postcode must be present for a soft match to be possible. When several existing
587	     * owners qualify the one with the lowest id is chosen. Returns the matching owner's id, or
588	     * {@code null} when there is no soft match. This is evaluated after the hard-duplicate check has
589	     * already passed, so any owner sharing the lastName and postcode necessarily differs in telephone.
590	     *
591	     * <p>Because the household is now keyed on {@code (lastName, postcode)} - exactly the soft-match
592	     * key - a co-member reached here can only be one the caller declared via {@code sharesHousehold}
593	     * (otherwise the hard household-duplicate check would already have rejected it). A declared
594	     * household member is not a suspected duplicate, so no soft match is reported in that case.
595	     */
596	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone) {
597	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
598	            return null;
599	        }
600	        String postcode = ownerFieldsDto.getPostcode();
601	        if (postcode == null) {
602	            return null;
603	        }
604	        String lastName = ownerFieldsDto.getLastName();
605	        Integer matchId = null;
606	        for (Owner existing : this.clinicService.findAllOwners()) {
607	            if (existing.isDeleted()) {
608	                continue;
609	            }
610	            if (lastName == null || !lastName.equalsIgnoreCase(existing.getLastName())) {
611	                continue;
612	            }
613	            if (!postcode.equals(existing.getPostcode())) {
614	                continue;
615	            }
616	            String existingTelephone;
617	            try {
618	                existingTelephone = normalizeTelephone(existing.getTelephone());
619	            } catch (InvalidTelephoneException ex) {
620	                existingTelephone = null;
621	            }
622	            if (normalizedTelephone.equals(existingTelephone)) {
623	                continue;
624	            }
625	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
626	                matchId = existing.getId();
627	            }
628	        }
629	        return matchId;
630	    }
631	
632	    /**
633	     * The tenure, in elapsed fiscal years, that an owner must exceed before its tenure contributes
634	     * membership points. Tenure is measured from the owner's {@code registrationDate}, so a newly
635	     * created owner (whose tenure is zero) never satisfies this and thus never earns the tenure
636	     * points on create.
637	     */
638	    private static final int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
639	
640	    /**
641	     * The household size (number of members) at or above which an owner earns the household points.
642	     */
643	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
644	
645	    /**
646	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
647	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
648	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
649	     * (elapsed fiscal years since its {@code registrationDate}) exceeds
650	     * {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS}. Because a newly created owner has zero tenure,
651	     * the tenure points never apply on create.
652	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
653	     * have been set.
654	     */
655	    private static int membershipPointsFor(Owner owner) {
656	        int points = 0;
657	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
658	            points += 2;
659	        }
660	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
661	            points += 1;
662	        }
663	        if (owner.getHouseholdMemberCount() != null
664	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
665	            points += 2;
666	        }
667	        if (tenureInFiscalYears(owner) > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
668	            points += 3;
669	        }
670	        return points;
671	    }
672	
673	    /**
674	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
675	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
676	     */
677	    private static int membershipLevelForPoints(int points) {
678	        if (points <= 1) {
679	            return 1;
680	        }
681	        if (points <= 3) {
682	            return 2;
683	        }
684	        if (points <= 5) {
685	            return 3;
686	        }
687	        return 4;
688	    }
689	
690	    /**
691	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July fiscal-year boundaries
692	     * crossed between its {@code registrationDate} and the current server date. An owner with no
693	     * registration date, or one dated in the future, has a tenure of zero.
694	     */
695	    private static long tenureInFiscalYears(Owner owner) {
696	        LocalDate registrationDate = owner.getRegistrationDate();
697	        if (registrationDate == null) {
698	            return 0;
699	        }
700	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate));
701	    }
702	
703	    /**
704	     * The maximum number of owners any single city may contain. A create whose city already
705	     * holds this many owners is rejected.
706	     */
707	    private static final int CITY_CAPACITY = 50;
708	
709	    /**
710	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
711	     * compared case-insensitively - the same way the city is matched when building the
712	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
713	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
714	     * translates to a 409.
715	     */
716	    private void rejectCityAtCapacity(String city) {
717	        int count = 0;
718	        for (Owner existing : this.clinicService.findAllOwners()) {
719	            if (city.equalsIgnoreCase(existing.getCity())) {
720	                count++;
721	            }
722	        }
723	        if (count >= CITY_CAPACITY) {
724	            throw new CityAtCapacityException(city);
725	        }
726	    }
727	
728	    /**
729	     * The maximum number of owners that may be created on any single day (by
730	     * {@code registrationDate}). A create attempted once this many owners already carry the
731	     * current day's registration date is rejected.
732	     */
733	    private static final int DAILY_OWNER_LIMIT = 100;
734	
735	    /**
736	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
737	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
738	     * The count reflects the state prior to this create. When the limit is reached the create is
739	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
740	     * to a 429 Too Many Requests.
741	     */
742	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
743	        int count = 0;
744	        for (Owner existing : this.clinicService.findAllOwners()) {
745	            if (registrationDate.equals(existing.getRegistrationDate())) {
746	                count++;
747	            }
748	        }
749	        if (count >= DAILY_OWNER_LIMIT) {
750	            throw new DailyOwnerLimitExceededException();
751	        }
752	    }
753	
754	    /**
755	     * The number of owners that must already carry a given {@code registrationDate} before a
756	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
757	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
758	     */
759	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
760	
761	    /**
762	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
763	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
764	     * have already been created for that date, otherwise false. The count reflects the state prior
765	     * to this create, matching how the daily-limit rule accumulates.
766	     */
767	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
768	        int count = 0;
769	        for (Owner existing : this.clinicService.findAllOwners()) {
770	            if (registrationDate.equals(existing.getRegistrationDate())) {
771	                count++;
772	            }
773	        }
774	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
775	    }
776	
777	    /**
778	     * Rolls an effective registration date forward onto a business day. A Saturday, Sunday or listed
779	     * public holiday is advanced to the next non-holiday business day; a plain weekday is returned
780	     * unchanged. This is applied to the effective registration date - whether supplied in the request
781	     * or defaulted to the server date - so the stored {@code registrationDate}, and everything derived
782	     * from it, always falls on a business day.
783	     */
784	    /**
785	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
786	     * only ever explicitly supplied on the request; when present it must not be later than the
787	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
788	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
789	     * later from the server date) is accepted.
790	     */
791	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
792	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
793	            throw new FutureRegistrationDateException(registrationDate);
794	        }
795	    }
796	
797	    /**
798	     * The fixed list of public holidays. An effective registration date that lands on any of these
799	     * is rolled forward, together with weekends, to the next non-holiday business day.
800	     */
801	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
802	        LocalDate.of(2026, 1, 1),
803	        LocalDate.of(2026, 1, 26),
804	        LocalDate.of(2026, 4, 25),
805	        LocalDate.of(2026, 12, 25),
806	        LocalDate.of(2026, 12, 28));
807	
808	    private static LocalDate toBusinessDay(LocalDate date) {
809	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
810	            date = date.plusDays(1);
811	        }
812	        return date;
813	    }
814	
815	    private static boolean isWeekend(LocalDate date) {
816	        return switch (date.getDayOfWeek()) {
817	            case SATURDAY, SUNDAY -> true;
818	            default -> false;
819	        };
820	    }
821	
822	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
823	    @Override
824	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
825	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
826	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
827	            OwnerDto replay = idempotentCreates.get(idempotencyKey);
828	            if (replay != null) {
829	                return new ResponseEntity<>(replay, HttpStatus.OK);
830	            }
831	        }
832	        String normalizedLine1 = null;
833	        String normalizedLine2 = null;
834	        String composedAddress;
835	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
836	            normalizedLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
837	            if (!isBlank(ownerFieldsDto.getAddressLine2())) {
838	                normalizedLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
839	            }
840	            composedAddress = normalizedLine2 == null
841	                ? normalizedLine1
842	                : normalizedLine1 + " " + normalizedLine2;
843	        } else {
844	            composedAddress = normalizeAddress(ownerFieldsDto.getAddress());
845	        }
846	        rejectMissingOrBlankFields(ownerFieldsDto, composedAddress);
847	        rejectCityAtCapacity(ownerFieldsDto.getCity());
848	        HttpHeaders headers = new HttpHeaders();
849	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
850	        owner.setAddress(composedAddress);
851	        owner.setAddressLine1(normalizedLine1);
852	        owner.setAddressLine2(normalizedLine2);
853	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
854	        owner.setTelephone(normalizedTelephone);
855	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
856	        owner.setEmail(normalizedEmail);
857	        validatePostcode(owner.getCity(), owner.getPostcode());
858	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
859	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
860	        rejectFutureRegistrationDate(owner.getRegistrationDate());
861	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
862	        LocalDate registrationDate = toBusinessDay(effectiveDate);
863	        rejectDailyOwnerLimit(registrationDate);
864	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
865	        owner.setRegistrationDate(registrationDate);
866	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
867	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName())));
868	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
869	        owner.setHouseholdId(householdId);
870	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
871	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
872	        int membershipPoints = membershipPointsFor(owner);
873	        owner.setMembershipPoints(membershipPoints);
874	        owner.setMembershipLevel(membershipLevelForPoints(membershipPoints));
875	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone);
876	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
877	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
878	        this.clinicService.saveOwner(owner);
879	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
880	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(), owner.getMembershipNumber());
881	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
882	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
883	            idempotentCreates.put(idempotencyKey, ownerDto);
884	        }
885	        headers.setLocation(UriComponentsBuilder.newInstance()
886	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
887	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
888	    }
889	
890	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
891	    @Override
892	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
893	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
894	        if (currentOwner == null) {
895	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
896	        }
897	        currentOwner.setAddress(ownerFieldsDto.getAddress());
898	        currentOwner.setCity(ownerFieldsDto.getCity());
899	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
900	        currentOwner.setLastName(ownerFieldsDto.getLastName());
901	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
902	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
903	        this.clinicService.saveOwner(currentOwner);
904	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
905	    }
906	
907	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
908	    @Transactional
909	    @Override
910	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
911	        Owner owner = this.clinicService.findOwnerById(ownerId);
912	        if (owner == null) {
913	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
914	        }
915	        owner.setDeleted(true);
916	        this.clinicService.saveOwner(owner);
917	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
918	    }
919	
920	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
921	    @Override
922	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
923	        Owner owner = this.clinicService.findOwnerById(ownerId);
924	        if (owner == null) {
925	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
926	        }
927	        HttpHeaders headers = new HttpHeaders();
928	        Pet pet = petMapper.toPet(petFieldsDto);
929	        owner.setId(ownerId);
930	        pet.setOwner(owner);
931	        pet.getType().setName(null);
932	        this.clinicService.savePet(pet);
933	        PetDto petDto = petMapper.toPetDto(pet);
934	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
935	            .buildAndExpand(pet.getId()).toUri());
936	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
937	    }
938	
939	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
940	    @Override
941	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
942	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
943	        if (currentOwner != null) {
944	            Pet currentPet = this.clinicService.findPetById(petId);
945	            if (currentPet != null) {
946	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
947	                currentPet.setName(petFieldsDto.getName());
948	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
949	                this.clinicService.savePet(currentPet);
950	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
951	            }
952	        }
953	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
954	    }
