956	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
957	    @Override
958	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
959	        HttpHeaders headers = new HttpHeaders();
960	        Visit visit = visitMapper.toVisit(visitFieldsDto);
961	        Pet pet = new Pet();
962	        pet.setId(petId);
963	        visit.setPet(pet);
964	        this.clinicService.saveVisit(visit);
965	        VisitDto visitDto = visitMapper.toVisitDto(visit);
966	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
967	            .buildAndExpand(visit.getId()).toUri());
968	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
969	    }
970	
971	
972	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
973	    @Override
974	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
975	        Owner owner = this.clinicService.findOwnerById(ownerId);
976	        if (owner != null) {
977	            Pet pet = owner.getPet(petId);
978	            if (pet != null) {
979	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
980	            }
981	        }
982	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
983	    }
